def resume_classe(notes):
    t = 0
    m = None
    a = 0
    for n in notes:
        t += n
        if m is None or n > m:
            m = n
        if n > 10:
            a += 1
    return [t / len(notes) if notes else 0, m, a]

exercises.solution:
def moyenne(notes):
    return sum(notes) / len(notes) if notes else 0


def meilleure(notes):
    return max(notes) if notes else None


def nb_admis(notes):
    return len([n for n in notes if n >= 10])


def resume_classe(notes):
    return [moyenne(notes), meilleure(notes), nb_admis(notes)]

def ligne_ticket(nom, quantite, prix):
    return f"{nom} x {quantite} = {quantite * prix}"


def ticket(articles):
    lignes = [ligne_ticket(nom, quantite, prix) for nom, quantite, prix in articles]
    total = sum(quantite * prix for _, quantite, prix in articles)
    return lignes + [f"Total = {total}"]
